-- Default watchlist for test user
INSERT INTO Watchlist (user_id, anime_id, status)
SELECT u.user_id, a.anime_id, v.status
FROM User u
JOIN (
    SELECT 'Attack on Titan'                  AS title, 'COMPLETED'     AS status
    UNION ALL SELECT 'Death Note',                       'COMPLETED'
    UNION ALL SELECT 'Fullmetal Alchemist: Brotherhood', 'COMPLETED'
    UNION ALL SELECT 'Jujutsu Kaisen',                   'WATCHING'
    UNION ALL SELECT 'Demon Slayer',                     'WATCHING'
    UNION ALL SELECT 'Naruto',                           'COMPLETED'
    UNION ALL SELECT 'Naruto Shippuden',                 'PLAN_TO_WATCH'
    UNION ALL SELECT 'One Piece',                        'ON_HOLD'
    UNION ALL SELECT 'Steins;Gate',                      'COMPLETED'
    UNION ALL SELECT 'Vinland Saga',                     'PLAN_TO_WATCH'
) AS v ON 1=1
JOIN Anime a ON a.title = v.title
WHERE u.username = 'testuser'
ON DUPLICATE KEY UPDATE status = status;

