-- View detailed list of users anime watchlist with list of show details
CREATE OR REPLACE VIEW user_watchlist_info AS
SELECT u.user_id, u.username, a.anime_id, a.title, a.genre, a.release_year, a.description, w.watchlist_id
FROM Watchlist w
LEFT JOIN User u ON w.user_id = u.user_id
LEFT JOIN Anime a ON a.anime_id = w.anime_id;


